## 3. RESTful API Architecture

### API Endpoint Structure

```typescript
// Authentication Routes
POST   /api/v1/auth/register
POST   /api/v1/auth/login
POST   /api/v1/auth/logout
POST   /api/v1/auth/refresh
GET    /api/v1/auth/me

// User Management
GET    /api/v1/users/profile
PUT    /api/v1/users/profile
DELETE /api/v1/users/account

// Barbershop Management
GET    /api/v1/barbershops
POST   /api/v1/barbershops
GET    /api/v1/barbershops/:id
PUT    /api/v1/barbershops/:id
DELETE /api/v1/barbershops/:id

// Barber Management
GET    /api/v1/barbershops/:barbershopId/barbers
POST   /api/v1/barbershops/:barbershopId/barbers
GET    /api/v1/barbers/:id
PUT    /api/v1/barbers/:id
DELETE /api/v1/barbers/:id
GET    /api/v1/barbers/:id/availability
PUT    /api/v1/barbers/:id/working-hours

// Service Management
GET    /api/v1/barbershops/:barbershopId/services
POST   /api/v1/barbershops/:barbershopId/services
GET    /api/v1/services/:id
PUT    /api/v1/services/:id
DELETE /api/v1/services/:id

// Appointment Management
GET    /api/v1/appointments
POST   /api/v1/appointments
GET    /api/v1/appointments/:id
PUT    /api/v1/appointments/:id
DELETE /api/v1/appointments/:id
GET    /api/v1/barbershops/:barbershopId/appointments
GET    /api/v1/barbers/:barberId/appointments

// Availability & Scheduling
GET    /api/v1/barbers/:barberId/available-slots?date=2025-01-15
POST   /api/v1/appointments/check-availability
```

### API Response Format

```typescript
// Success Response
{
  "success": true,
  "data": {
    // Response data
  },
  "meta": {
    "page": 1,
    "limit": 20,
    "total": 100
  }
}

// Error Response
{
  "success": false,
  "error": {
    "code": "VALIDATION_ERROR",
    "message": "Invalid input data",
    "details": [
      {
        "field": "email",
        "message": "Email is required"
      }
    ]
  }
}
```

### Example API Endpoints Implementation

```typescript
// Appointment booking endpoint
POST /api/v1/appointments
{
  "barbershop_id": "uuid",
  "barber_id": "uuid",
  "service_id": "uuid",
  "appointment_date": "2025-01-15",
  "start_time": "10:00",
  "notes": "First time customer"
}

// Get available time slots
GET /api/v1/barbers/123/available-slots?date=2025-01-15
Response:
{
  "success": true,
  "data": [
    {
      "start_time": "09:00",
      "end_time": "09:30",
      "available": true
    },
    {
      "start_time": "09:30",
      "end_time": "10:00",
      "available": false
    }
  ]
}
```

## 4. Authentication & Authorization Strategy

### JWT-Based Authentication with Refresh Tokens

```typescript
// Authentication Flow
1. User logs in → Server validates credentials
2. Server generates Access Token (15 minutes) + Refresh Token (7 days)
3. Access Token stored in memory, Refresh Token in httpOnly cookie
4. Client includes Access Token in Authorization header
5. When Access Token expires, use Refresh Token to get new tokens

// Token Structure
interface JWTPayload {
  userId: string;
  email: string;
  role: 'CUSTOMER' | 'BARBER' | 'ADMIN';
  barbershopId?: string; // Only for barbers/admins
  iat: number;
  exp: number;
}
```

### Role-Based Access Control (RBAC)

```typescript
// Permission Matrix
const PERMISSIONS = {
  CUSTOMER: [
    'appointments.create',
    'appointments.view.own',
    'appointments.update.own',
    'appointments.cancel.own',
    'profile.update.own'
  ],
  BARBER: [
    'appointments.view.assigned',
    'appointments.update.assigned',
    'schedule.manage.own',
    'services.view',
    'profile.update.own'
  ],
  ADMIN: [
    'barbershop.manage',
    'barbers.manage',
    'services.manage',
    'appointments.view.all',
    'analytics.view'
  ]
};

// Middleware Implementation
const authorize = (permission: string) => {
  return (req: Request, res: Response, next: NextFunction) => {
    const userRole = req.user.role;
    if (PERMISSIONS[userRole].includes(permission)) {
      next();
    } else {
      res.status(403).json({ error: 'Insufficient permissions' });
    }
  };
};
```

### Security Measures

```typescript
// Rate Limiting
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts per window
  message: 'Too many login attempts'
});

// Password Requirements
const passwordSchema = z.string()
  .min(8, 'Password must be at least 8 characters')
  .regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/, 
    'Password must contain uppercase, lowercase, number, and special character');

// CORS Configuration
const corsOptions = {
  origin: process.env.FRONTEND_URL,
  credentials: true,
  optionsSuccessStatus: 200
};
```

## 6. Scaling Considerations & Performance Optimization

### Potential Bottlenecks

1. **Database Query Performance**
   - High-frequency appointment lookups
   - Availability calculations
   - Complex reporting queries

2. **Real-time Features**
   - Calendar updates
   - Appointment notifications
   - Availability synchronization

3. **Concurrent Booking Conflicts**
   - Multiple users booking same time slot
   - Race conditions in availability checks

### Performance Solutions

```typescript
// 1. Database Optimization
// Implement proper indexing
CREATE INDEX CONCURRENTLY idx_appointments_composite 
ON appointments(barber_id, appointment_date, start_time);

// Use database-level constraints for booking conflicts
ALTER TABLE appointments ADD CONSTRAINT unique_barber_datetime 
EXCLUDE USING gist (
  barber_id WITH =,
  tsrange(appointment_date + start_time, appointment_date + end_time) WITH &&
);

// 2. Caching Strategy
interface CacheStrategy {
  // Cache barber availability for 5 minutes
  'barber:availability:{barberId}:{date}': {
    ttl: 300,
    data: TimeSlot[]
  };

  // Cache barbershop services for 1 hour
  'barbershop:services:{barbershopId}': {
    ttl: 3600,
    data: Service[]
  };

  // Cache user sessions
  'session:{userId}': {
    ttl: 900, // 15 minutes
    data: UserSession
  };
}

// 3. Background Job Processing
const appointmentQueues = {
  'reminder-notifications': {
    // Send appointment reminders
    delay: '24 hours before appointment'
  },
  'availability-sync': {
    // Sync availability across systems
    repeat: { cron: '*/5 * * * *' } // Every 5 minutes
  },
  'cleanup-expired-slots': {
    // Clean up past time slots
    repeat: { cron: '0 2 * * *' } // Daily at 2 AM
  }
});
```

### Horizontal Scaling Architecture

```typescript
// Load Balancer Configuration
const loadBalancerConfig = {
  algorithm: 'round-robin',
  healthCheck: '/health',
  nodes: [
    'api-server-1:3000',
    'api-server-2:3000',
    'api-server-3:3000'
  ]
};

// Database Connection Pooling
const dbConfig = {
  max: 20,           // Maximum connections
  min: 5,            // Minimum connections
  acquire: 30000,    // Maximum time to get connection
  idle: 10000,       // Maximum time connection can be idle
};

// Redis Cluster for Session Storage
const redisCluster = {
  nodes: [
    { host: 'redis-1', port: 6379 },
    { host: 'redis-2', port: 6379 },
    { host: 'redis-3', port: 6379 }
  ]
};
```

### Monitoring & Analytics

```typescript
// Key Metrics to Track
const monitoringMetrics = {
  performance: [
    'api_response_time',
    'database_query_time',
    'cache_hit_ratio',
    'error_rate'
  ],
  business: [
    'appointments_booked_per_hour',
    'cancellation_rate',
    'barber_utilization',
    'customer_retention'
  ],
  system: [
    'cpu_usage',
    'memory_usage',
    'database_connections',
    'active_sessions'
  ]
};

// Alert Thresholds
const alerts = {
  high_response_time: '> 500ms',
  high_error_rate: '> 5%',
  low_cache_hit_ratio: '< 80%',
  high_database_load: '> 80% connections used'
};
```

