export interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  phone?: string;
  avatar?: string;
  role: 'CUSTOMER' | 'BARBER' | 'SHOP_OWNER' | 'ADMIN';
  emailVerified: boolean;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface Barbershop {
  id: string;
  name: string;
  description?: string;
  address: string;
  city: string;
  state: string;
  zipCode: string;
  phone: string;
  email?: string;
  website?: string;
  images: string[];
  latitude?: number;
  longitude?: number;
  rating: number;
  reviewCount: number;
  isActive: boolean;
  businessHours?: Record<string, { open: string; close: string }>;
  ownerId: string;
  createdAt: string;
  updatedAt: string;
}

export interface Barber {
  id: string;
  bio?: string;
  specialties: string[];
  experience?: number;
  avatar?: string;
  rating: number;
  reviewCount: number;
  isAvailable: boolean;
  userId: string;
  barbershopId: string;
  user: User;
  createdAt: string;
  updatedAt: string;
}

export interface Service {
  id: string;
  name: string;
  description?: string;
  duration: number;
  price: number;
  category?: string;
  isActive: boolean;
  barbershopId: string;
  createdAt: string;
  updatedAt: string;
}

export interface Appointment {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
  status: 'PENDING' | 'CONFIRMED' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED' | 'NO_SHOW';
  notes?: string;
  totalPrice: number;
  paymentStatus: 'PENDING' | 'COMPLETED' | 'FAILED' | 'REFUNDED';
  customerId: string;
  barberId: string;
  serviceId: string;
  barbershopId: string;
  customer: User;
  barber: Barber;
  service: Service;
  barbershop: Barbershop;
  createdAt: string;
  updatedAt: string;
}

export interface Review {
  id: string;
  rating: number;
  comment?: string;
  customerId: string;
  barberId: string;
  barbershopId: string;
  appointmentId: string;
  customer: User;
  createdAt: string;
  updatedAt: string;
}

export interface AuthResponse {
  message: string;
  user: User;
  token: string;
  refreshToken: string;
}

export interface ApiError {
  error: string;
  details?: any;
}

