export interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  phone?: string;
  avatar?: string;
  role: 'CUSTOMER' | 'BARBER' | 'SHOP_OWNER' | 'ADMIN';
  emailVerified: boolean;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface Barbershop {
  id: string;
  name: string;
  description?: string;
  address: string;
  city: string;
  state: string;
  zipCode: string;
  phone: string;
  email?: string;
  website?: string;
  images: string[];
  latitude?: number;
  longitude?: number;
  rating: number;
  reviewCount: number;
  isActive: boolean;
  businessHours?: Record<string, { open: string; close: string }>;
  ownerId: string;
  createdAt: string;
  updatedAt: string;
}

export interface Barber {
  id: string;
  bio?: string;
  specialties: string[];
  experience?: number;
  avatar?: string;
  rating: number;
  reviewCount: number;
  isAvailable: boolean;

  // Enhanced management fields
  hireDate: string;
  commissionRate: number;
  hourlyRate?: number;
  certifications: string[];
  languages: string[];
  portfolio: string[];
  socialMedia?: Record<string, string>;
  isActive: boolean;

  // Performance metrics
  totalRevenue: number;
  totalAppointments: number;
  cancelationRate: number;

  userId: string;
  barbershopId: string;
  user: User;
  barbershop?: Barbershop;
  services?: Service[];
  schedules?: Schedule[];
  reviews?: Review[];
  _count?: {
    appointments: number;
    reviews: number;
  };
  createdAt: string;
  updatedAt: string;
}

export interface Service {
  id: string;
  name: string;
  description?: string;
  duration: number;
  price: number;
  category?: string;
  isActive: boolean;
  barbershopId: string;
  createdAt: string;
  updatedAt: string;
}

export interface Appointment {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
  status: 'PENDING' | 'CONFIRMED' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED' | 'NO_SHOW';
  notes?: string;
  totalPrice: number;
  paymentStatus: 'PENDING' | 'COMPLETED' | 'FAILED' | 'REFUNDED';
  customerId: string;
  barberId: string;
  serviceId: string;
  barbershopId: string;
  customer: User;
  barber: Barber;
  service: Service;
  barbershop: Barbershop;
  createdAt: string;
  updatedAt: string;
}

export interface Review {
  id: string;
  rating: number;
  comment?: string;
  customerId: string;
  barberId: string;
  barbershopId: string;
  appointmentId: string;
  customer: User;
  createdAt: string;
  updatedAt: string;
}

export interface AuthResponse {
  message: string;
  user: User;
  token: string;
  refreshToken: string;
}

export interface ApiError {
  error: string;
  details?: any;
}

export interface Schedule {
  id: string;
  dayOfWeek: number; // 0 = Sunday, 1 = Monday, etc.
  startTime: string; // HH:mm format
  endTime: string; // HH:mm format
  isActive: boolean;
  barberId: string;
  createdAt: string;
  updatedAt: string;
}

export interface WeeklySchedule {
  dayOfWeek: number;
  dayName: string;
  isActive: boolean;
  startTime: string | null;
  endTime: string | null;
  scheduleId: string | null;
}

export interface BarberPerformance {
  period: {
    startDate: string;
    endDate: string;
  };
  metrics: {
    totalAppointments: number;
    completedAppointments: number;
    cancelledAppointments: number;
    cancellationRate: number;
    totalRevenue: number;
    commissionEarned: number;
    averageRating: number;
    totalReviews: number;
  };
  appointments: Array<{
    id: string;
    date: string;
    status: string;
    totalPrice: number;
    serviceName: string;
  }>;
}

export interface BarberSearchParams {
  search?: string;
  barbershopId?: string;
  specialties?: string[];
  isAvailable?: boolean;
  minRating?: number;
  sortBy?: 'createdAt' | 'rating' | 'firstName' | 'lastName' | 'experience';
  sortOrder?: 'asc' | 'desc';
  page?: number;
  limit?: number;
}

export interface BarberSearchResponse {
  barbers: Barber[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    pages: number;
  };
}

export interface CreateBarberData {
  userId: string;
  barbershopId: string;
  bio?: string;
  specialties?: string[];
  experience?: number;
  hireDate?: string;
  commissionRate?: number;
  hourlyRate?: number;
  certifications?: string[];
  languages?: string[];
  socialMedia?: Record<string, string>;
  avatar?: File;
  portfolio?: File[];
}

export interface UpdateBarberData {
  bio?: string;
  specialties?: string[];
  experience?: number;
  hireDate?: string;
  commissionRate?: number;
  hourlyRate?: number;
  certifications?: string[];
  languages?: string[];
  socialMedia?: Record<string, string>;
  isAvailable?: boolean;
  isActive?: boolean;
  avatar?: File;
  portfolio?: File[];
}

