  async getRecurringAppointments(
    pattern: RecurringPattern,
    start: Date,
    end: Date
  ): Promise<Appointment[]> {
    const response = await api.post('/appointments/recurring/preview', {
      pattern,
      start: formatISO(start),
      end: formatISO(end)
    });
    return response.data;
  },

  /**
   * Create recurring appointments
