    const userId = req.user!.id;
    const userRole = req.user!.role;

    // Build query
    const where: any = {
      startTime: {
        gte: new Date(start as string),
        lte: new Date(end as string)
      }
    };

    if (userRole === UserRole.CUSTOMER) {
      where.customerId = userId;
