     1→import { Router } from 'express';
     2→import { PrismaClient, UserRole, AppointmentStatus, PaymentStatus } from '@prisma/client';
     3→import { authenticate, authorize } from '../middleware/auth';
     4→import { validateRequest } from '../middleware/validation';
     5→import { z } from 'zod';
     6→
     7→const router = Router();
     8→const prisma = new PrismaClient();
     9→
    10→// Validation schemas
    11→const getAppointmentsSchema = z.object({
    12→  query: z.object({
    13→    start: z.string().optional(),
    14→    end: z.string().optional(),
    15→    barberId: z.string().optional(),
    16→    barberIds: z.string().optional(),
    17→    status: z.string().optional(),
    18→    serviceId: z.string().optional(),
    19→    page: z.string().optional(),
    20→    limit: z.string().optional()
    21→  })
    22→});
    23→
    24→const createAppointmentSchema = z.object({
    25→  body: z.object({
    26→    customerId: z.string(),
    27→    barberId: z.string(),
    28→    serviceId: z.string(),
    29→    date: z.string(),
    30→    startTime: z.string(),
    31→    endTime: z.string(),
    32→    notes: z.string().optional(),
    33→    recurring: z.object({
    34→      type: z.enum(['daily', 'weekly', 'monthly']),
    35→      interval: z.number().min(1).max(30),
    36→      daysOfWeek: z.array(z.number().min(0).max(6)).optional(),
    37→      endDate: z.string().optional(),
    38→      occurrences: z.number().optional()
    39→    }).optional()
    40→  })
    41→});
    42→
    43→const updateAppointmentSchema = z.object({
    44→  body: z.object({
    45→    date: z.string().optional(),
    46→    startTime: z.string().optional(),
    47→    endTime: z.string().optional(),
    48→    status: z.nativeEnum(AppointmentStatus).optional(),
    49→    notes: z.string().optional(),
    50→    barberId: z.string().optional(),
    51→    serviceId: z.string().optional()
    52→  })
    53→});
    54→
    55→const moveAppointmentSchema = z.object({
    56→  body: z.object({
    57→    startTime: z.string(),
    58→    endTime: z.string(),
    59→    barberId: z.string().optional()
    60→  })
    61→});
    62→
    63→/**
    64→ * @route   GET /api/appointments
    65→ * @desc    Get appointments with filtering
    66→ * @access  Private
    67→ */
    68→router.get('/', authenticate, validateRequest(getAppointmentsSchema), async (req, res) => {
    69→  try {
    70→    const { start, end, barberId, barberIds, status, serviceId, page = '1', limit = '50' } = req.query;
    71→    const userId = req.user!.id;
    72→    const userRole = req.user!.role;
    73→
    74→    // Build where clause based on user role and filters
    75→    const where: any = {};
    76→
    77→    // Role-based filtering
    78→    if (userRole === UserRole.CUSTOMER) {
    79→      where.customerId = userId;
    80→    } else if (userRole === UserRole.BARBER) {
    81→      const barber = await prisma.barber.findUnique({
    82→        where: { userId }
    83→      });
    84→      if (barber) {
    85→        where.barberId = barber.id;
    86→      }
    87→    } else if (userRole === UserRole.SHOP_OWNER) {
    88→      // Get appointments for barbers in shops owned by this user
    89→      const ownedShops = await prisma.barbershop.findMany({
    90→        where: { ownerId: userId },
    91→        select: { id: true }
    92→      });
    93→      const shopIds = ownedShops.map(shop => shop.id);
    94→      where.barbershopId = { in: shopIds };
    95→    }
    96→
    97→    // Date range filtering
    98→    if (start || end) {
    99→      where.date = {};
   100→      if (start) where.date.gte = new Date(start);
   101→      if (end) where.date.lte = new Date(end);
   102→    }
   103→
   104→    // Barber filtering
   105→    if (barberId) {
   106→      where.barberId = barberId;
   107→    } else if (barberIds) {
   108→      where.barberId = { in: barberIds.split(',') };
   109→    }
   110→
   111→    // Status filtering
   112→    if (status) {
   113→      where.status = { in: status.split(',') };
   114→    }
   115→
   116→    // Service filtering
   117→    if (serviceId) {
   118→      where.serviceId = serviceId;
   119→    }
   120→
   121→    const pageNum = parseInt(page);
   122→    const limitNum = parseInt(limit);
   123→    const skip = (pageNum - 1) * limitNum;
   124→
   125→    const [appointments, total] = await Promise.all([
   126→      prisma.appointment.findMany({
   127→        where,
   128→        include: {
   129→          customer: true,
   130→          barber: {
   131→            include: {
   132→              user: true
   133→            }
   134→          },
   135→          service: true,
   136→          barbershop: true,
   137→          payment: true
   138→        },
   139→        orderBy: {
   140→          startTime: 'asc'
   141→        },
   142→        skip,
   143→        take: limitNum
   144→      }),
   145→      prisma.appointment.count({ where })
   146→    ]);
   147→
   148→    res.json({
   149→      appointments,
   150→      pagination: {
   151→        page: pageNum,
   152→        limit: limitNum,
   153→        total,
   154→        pages: Math.ceil(total / limitNum)
   155→      }
   156→    });
   157→  } catch (error) {
   158→    console.error('Error fetching appointments:', error);
   159→    res.status(500).json({ error: 'Failed to fetch appointments' });
   160→  }
   161→});
   162→
   163→/**
   164→ * @route   POST /api/appointments
   165→ * @desc    Create appointment
   166→ * @access  Private
   167→ */
   168→router.post('/', authenticate, validateRequest(createAppointmentSchema), async (req, res) => {
   169→  try {
   170→    const { customerId, barberId, serviceId, date, startTime, endTime, notes, recurring } = req.body;
   171→
   172→    // Get service details for pricing
   173→    const service = await prisma.service.findUnique({
   174→      where: { id: serviceId }
   175→    });
   176→
   177→    if (!service) {
   178→      return res.status(404).json({ error: 'Service not found' });
   179→    }
   180→
   181→    // Check for conflicts
   182→    const conflictingAppointments = await prisma.appointment.findMany({
   183→      where: {
   184→        barberId,
   185→        date: new Date(date),
   186→        OR: [
   187→          {
   188→            AND: [
   189→              { startTime: { lte: new Date(startTime) } },
   190→              { endTime: { gt: new Date(startTime) } }
   191→            ]
   192→          },
   193→          {
   194→            AND: [
   195→              { startTime: { lt: new Date(endTime) } },
   196→              { endTime: { gte: new Date(endTime) } }
   197→            ]
   198→          },
   199→          {
   200→            AND: [
   201→              { startTime: { gte: new Date(startTime) } },
   202→              { endTime: { lte: new Date(endTime) } }
   203→            ]
   204→          }
   205→        ],
   206→        status: {
   207→          not: AppointmentStatus.CANCELLED
   208→        }
   209→      }
   210→    });
   211→
   212→    if (conflictingAppointments.length > 0) {
   213→      return res.status(409).json({ error: 'Time slot is already booked' });
   214→    }
   215→
   216→    // Get barbershop for the appointment
   217→    const barber = await prisma.barber.findUnique({
   218→      where: { id: barberId },
   219→      include: { barbershop: true }
   220→    });
   221→
   222→    if (!barber) {
   223→      return res.status(404).json({ error: 'Barber not found' });
   224→    }
   225→
   226→    // Create the appointment
   227→    const appointment = await prisma.appointment.create({
   228→      data: {
   229→        customerId,
   230→        barberId,
   231→        serviceId,
   232→        barbershopId: barber.barbershopId,
   233→        date: new Date(date),
   234→        startTime: new Date(startTime),
   235→        endTime: new Date(endTime),
   236→        totalPrice: service.price,
   237→        notes,
   238→        status: AppointmentStatus.PENDING,
   239→        paymentStatus: PaymentStatus.PENDING
   240→      },
   241→      include: {
   242→        customer: true,
   243→        barber: {
   244→          include: {
   245→            user: true
   246→          }
   247→        },
   248→        service: true,
   249→        barbershop: true
   250→      }
   251→    });
   252→
   253→    // TODO: Handle recurring appointments if specified
   254→
   255→    res.status(201).json(appointment);
   256→  } catch (error) {
   257→    console.error('Error creating appointment:', error);
   258→    res.status(500).json({ error: 'Failed to create appointment' });
   259→  }
   260→});
   261→
   262→/**
   263→ * @route   PUT /api/appointments/:id
   264→ * @desc    Update appointment
   265→ * @access  Private
   266→ */
   267→router.put('/:id', authenticate, validateRequest(updateAppointmentSchema), async (req, res) => {
   268→  try {
   269→    const { id } = req.params;
   270→    const updates = req.body;
   271→
   272→    // Check if appointment exists and user has permission
   273→    const existingAppointment = await prisma.appointment.findUnique({
   274→      where: { id },
   275→      include: {
   276→        barber: {
