   413→// Helper function to generate time slots
   414→function generateTimeSlots(
   415→  date: Date, 
   416→  startTime: string, 
   417→  endTime: string, 
   418→  duration: number, 
   419→  existingAppointments: any[]
   420→) {
   421→  const slots = [];
   422→  const [startHour, startMinute] = startTime.split(':').map(Number);
   423→  const [endHour, endMinute] = endTime.split(':').map(Number);
   424→
   425→  const workStart = new Date(date);
   426→  workStart.setHours(startHour, startMinute, 0, 0);
   427→
   428→  const workEnd = new Date(date);
   429→  workEnd.setHours(endHour, endMinute, 0, 0);
   430→
   431→  const current = new Date(workStart);
   432→  const slotDuration = Math.max(duration, 30); // Minimum 30-minute slots
   433→
   434→  while (current < workEnd) {
   435→    const slotEnd = new Date(current);
   436→    slotEnd.setMinutes(current.getMinutes() + slotDuration);
   437→
   438→    if (slotEnd <= workEnd) {
   439→      // Check for conflicts
   440→      const hasConflict = existingAppointments.some(apt => 
   441→        (apt.startTime <= current && apt.endTime > current) ||
   442→        (apt.startTime < slotEnd && apt.endTime >= slotEnd) ||
   443→        (apt.startTime >= current && apt.endTime <= slotEnd)
   444→      );
   445→
   446→      if (!hasConflict) {
   447→        slots.push({
   448→          startTime: new Date(current),
   449→          endTime: new Date(slotEnd)
   450→        });
   451→      }
   452→    }
   453→
   454→    current.setMinutes(current.getMinutes() + 30); // 30-minute increments
   455→  }
   456→
   457→  return slots;
   458→}
