  title: string;
  start: Date;
  end: Date;
  barberId?: string; // null for shop-wide blocks
  isRecurring: boolean;
  recurringPattern?: RecurringPattern;
  color: string;
}

export interface CalendarExportOptions {
  format: 'ical' | 'google' | 'outlook';
  dateRange: {
    start: Date;
    end: Date;
  };
  includeCustomers: boolean;
  includeNotes: boolean;
  barberId?: string;
