    --primary-400: 214 100% 68%;
    --primary-500: 214 100% 58%;
    --primary-600: 214 100% 48%;
    --primary-700: 214 100% 38%;
    --primary-800: 214 100% 28%;
    --primary-900: 214 100% 18%;
    --primary-950: 214 100% 8%;

    /* Secondary colors */
    --secondary: 210 40% 96%;
    --secondary-foreground: 222.2 84% 4.9%;

    /* Semantic colors */
    --success: 142 76% 36%;
    --success-foreground: 0 0% 100%;
    --warning: 38 92% 50%;
    --warning-foreground: 0 0% 100%;
    --info: 199 89% 48%;
    --info-foreground: 0 0% 100%;
    --destructive: 0 84.2% 60.2%;
    --destructive-foreground: 210 40% 98%;

    /* Brand colors */
    --brand: 17 88% 40%;
    --brand-foreground: 0 0% 100%;

    /* Neutral colors */
    --muted: 210 40% 96%;
    --muted-foreground: 215.4 16.3% 46.9%;
    --accent: 210 40% 96%;
    --accent-foreground: 222.2 84% 4.9%;

    /* Interactive colors */
    --border: 214.3 31.8% 91.4%;
    --input: 214.3 31.8% 91.4%;
    --ring: 214 100% 34%;

    /* Border radius */
    --radius: 0.75rem;
  }

  .dark {
    /* Background colors */
    --background: 222.2 84% 4.9%;
    --foreground: 210 40% 98%;

    /* Card colors */
    --card: 222.2 84% 4.9%;
    --card-foreground: 210 40% 98%;

    /* Popover colors */
    --popover: 222.2 84% 4.9%;
    --popover-foreground: 210 40% 98%;

    /* Primary colors for dark mode */
    --primary: 214 100% 58%;
    --primary-foreground: 222.2 84% 4.9%;
    --primary-50: 214 100% 8%;
    --primary-100: 214 100% 18%;
    --primary-200: 214 100% 28%;
    --primary-300: 214 100% 38%;
    --primary-400: 214 100% 48%;
    --primary-500: 214 100% 58%;
    --primary-600: 214 100% 68%;
    --primary-700: 214 100% 78%;
    --primary-800: 214 100% 87%;
    --primary-900: 214 100% 93%;
    --primary-950: 214 100% 97%;

    /* Secondary colors */
    --secondary: 217.2 32.6% 17.5%;
    --secondary-foreground: 210 40% 98%;

    /* Semantic colors for dark mode */
    --success: 142 76% 46%;
    --success-foreground: 222.2 84% 4.9%;
    --warning: 38 92% 60%;
    --warning-foreground: 222.2 84% 4.9%;
    --info: 199 89% 58%;
    --info-foreground: 222.2 84% 4.9%;
    --destructive: 0 62.8% 30.6%;
    --destructive-foreground: 210 40% 98%;

    /* Brand colors for dark mode */
    --brand: 17 88% 50%;
    --brand-foreground: 222.2 84% 4.9%;

    /* Neutral colors */
    --muted: 217.2 32.6% 17.5%;
    --muted-foreground: 215 20.2% 65.1%;
    --accent: 217.2 32.6% 17.5%;
    --accent-foreground: 210 40% 98%;

    /* Interactive colors */
    --border: 217.2 32.6% 17.5%;
    --input: 217.2 32.6% 17.5%;
    --ring: 214 100% 58%;
  }
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground font-sans antialiased;
    font-feature-settings: "rlig" 1, "calt" 1;
  }

  h1, h2, h3, h4, h5, h6 {
    @apply font-heading;
  }
}

@layer components {
  /* Custom scroll bars */
  .scrollbar-thin {
    scrollbar-width: thin;
    scrollbar-color: hsl(var(--muted-foreground)) transparent;
  }

  .scrollbar-thin::-webkit-scrollbar {
    width: 8px;
  }

  .scrollbar-thin::-webkit-scrollbar-track {
    background: transparent;
  }

  .scrollbar-thin::-webkit-scrollbar-thumb {
    background-color: hsl(var(--muted-foreground));
    border-radius: 4px;
  }

  .scrollbar-thin::-webkit-scrollbar-thumb:hover {
    background-color: hsl(var(--foreground));
  }

  /* Focus styles */
  .focus-ring {
    @apply focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-background;
  }

  /* Glass morphism effect */
  .glass {
    @apply bg-white/20 backdrop-blur-md border border-white/20;
  }

  .dark .glass {
    @apply bg-black/20 backdrop-blur-md border border-white/10;
  }

  /* Gradient backgrounds */
  .gradient-primary {
    background: linear-gradient(135deg, hsl(var(--primary)) 0%, hsl(var(--primary-600)) 100%);
  }

  .gradient-brand {
    background: linear-gradient(135deg, hsl(var(--brand)) 0%, hsl(var(--primary)) 100%);
  }

  /* Text gradients */
  .text-gradient {
    @apply bg-gradient-to-r from-primary to-brand bg-clip-text text-transparent;
  }

  /* Loading states */
  .skeleton {
    @apply animate-pulse bg-muted rounded;
  }

  .shimmer {
    @apply relative overflow-hidden;
  }

  .shimmer::before {
    @apply absolute inset-0 -translate-x-full animate-shimmer bg-gradient-to-r from-transparent via-white/20 to-transparent;
    content: '';
  }

  .dark .shimmer::before {
    @apply via-white/10;
  }
}

@layer utilities {
  /* Animation utilities */
  .animate-in {
    @apply animate-fade-in;
  }

  .animate-out {
    @apply animate-fade-out;
  }

  /* Safe area utilities for mobile */
  .safe-top {
    padding-top: env(safe-area-inset-top);
  }

  .safe-bottom {
    padding-bottom: env(safe-area-inset-bottom);
  }

  .safe-left {
    padding-left: env(safe-area-inset-left);
  }

  .safe-right {
    padding-right: env(safe-area-inset-right);
  }
}

