  .gradient-primary {
    background: linear-gradient(135deg, hsl(var(--primary)) 0%, hsl(var(--primary-600)) 100%);
  }

  .gradient-brand {
    background: linear-gradient(135deg, hsl(var(--brand)) 0%, hsl(var(--primary)) 100%);
  }

  /* Text gradients */
  .text-gradient {
    @apply bg-gradient-to-r from-primary to-brand bg-clip-text text-transparent;
  }

  /* Loading states */
  .skeleton {
    @apply animate-pulse bg-muted rounded;
  }

  .shimmer {
    @apply relative overflow-hidden;
  }

  .shimmer::before {
    @apply absolute inset-0 -translate-x-full animate-shimmer bg-gradient-to-r from-transparent via-white/20 to-transparent;
    content: '';
  }

  .dark .shimmer::before {
    @apply via-white/10;
  }
}

@layer utilities {
  /* Animation utilities */
  .animate-in {
    @apply animate-fade-in;
  }

  .animate-out {
    @apply animate-fade-out;
  }

  /* Safe area utilities for mobile */
  .safe-top {
    padding-top: env(safe-area-inset-top);
  }

  .safe-bottom {
    padding-bottom: env(safe-area-inset-bottom);
  }

  .safe-left {
    padding-left: env(safe-area-inset-left);
  }

  .safe-right {
    padding-right: env(safe-area-inset-right);
  }
}

