import { rest } from 'msw';
import { UserRole, AppointmentStatus, PaymentStatus } from '@/types';

const BASE_URL = 'http://localhost:5000/api';

// Mock data
const mockUser = {
  id: 'user-1',
  email: 'test@example.com',
  firstName: 'Test',
  lastName: 'User',
  phone: '555-0123',
  role: UserRole.CUSTOMER,
  avatar: null,
  emailVerified: true,
  isActive: true,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
};

const mockBarber = {
  id: 'barber-1',
  userId: 'user-2',
  barbershopId: 'barbershop-1',
  bio: 'Experienced barber',
  specialties: ['haircut', 'beard'],
  experience: 5,
  rating: 4.8,
  reviewCount: 150,
  isAvailable: true,
  user: {
    id: 'user-2',
    firstName: 'John',
    lastName: 'Barber',
    avatar: null,
  },
};

const mockBarbershop = {
  id: 'barbershop-1',
  name: 'The Great Barbershop',
  description: 'A premium barbershop experience',
  address: '123 Main Street',
  city: 'San Francisco',
  state: 'CA',
  zipCode: '94101',
  phone: '415-555-0123',
  email: 'info@greatbarbershop.com',
  images: [],
  rating: 4.7,
  reviewCount: 200,
  isActive: true,
  barbers: [mockBarber],
  services: [
    {
      id: 'service-1',
      name: 'Haircut',
      description: 'Professional haircut',
      duration: 30,
      price: 25.00,
      category: 'Hair',
      isActive: true,
    },
    {
      id: 'service-2',
      name: 'Beard Trim',
      description: 'Professional beard trimming',
      duration: 15,
      price: 15.00,
      category: 'Beard',
      isActive: true,
    },
  ],
};

const mockAppointment = {
  id: 'appointment-1',
  customerId: 'user-1',
  barberId: 'barber-1',
  serviceId: 'service-1',
  barbershopId: 'barbershop-1',
  date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
  startTime: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
  endTime: new Date(Date.now() + 24 * 60 * 60 * 1000 + 30 * 60 * 1000).toISOString(),
  status: AppointmentStatus.PENDING,
  notes: 'Test appointment',
  totalPrice: 25.00,
  paymentStatus: PaymentStatus.PENDING,
  isGuestBooking: false,
  customer: mockUser,
  barber: mockBarber,
  service: mockBarbershop.services[0],
  barbershop: mockBarbershop,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
};

export const handlers = [
  // Auth endpoints
  rest.post(`${BASE_URL}/auth/register`, (req, res, ctx) => {
    return res(
      ctx.status(201),
      ctx.json({
        message: 'User created successfully',
        user: mockUser,
        token: 'mock-jwt-token',
        refreshToken: 'mock-refresh-token',
      })
    );
  }),

  rest.post(`${BASE_URL}/auth/login`, (req, res, ctx) => {
    return res(
      ctx.status(200),
      ctx.json({
        message: 'Login successful',
        user: mockUser,
        token: 'mock-jwt-token',
        refreshToken: 'mock-refresh-token',
      })
    );
  }),

  rest.post(`${BASE_URL}/auth/refresh`, (req, res, ctx) => {
