  email: 'test@barbershop.com',
  images: [],
  rating: 4.5,
  reviewCount: 100,
  isActive: true,
  barbers: [],
  services: [],
};

// Mock appointment data
export const mockAppointmentData = {
  id: 'test-appointment-1',
