    68→router.get('/', authenticate, validateRequest(getAppointmentsSchema), async (req, res) => {
    69→  try {
    70→    const { start, end, barberId, barberIds, status, serviceId, page = '1', limit = '50' } = req.query;
    71→    const userId = req.user!.id;
